-- ============================================================
-- CARGA DE DATOS DE PRUEBA - ENTREGA 2
-- ============================================================
--
-- Sobre que se apoya:
--   * Los datos de EDICION, SEDE, CIUDAD, ESTADIO, FASE, GRUPO,
--     SELECCION, PARTIDO y PARTICIPACION_PARTIDO vienen de la
--     carga probada de la Entrega 1, reacomodados al modelo
--     ampliado (la sede ya no es columna de edicion, el grupo y
--     la fase ya son llaves foraneas, y el partido apunta al
--     siguiente del cuadro).
--
--   * El detalle deportivo (JUGADOR, CONVOCATORIA, CUERPO
--     TECNICO, ARBITRO, ASIGNACION, ESTADISTICA e INCIDENCIA)
--     se carga para la edicion 7 (Catar 2022), la mas reciente.
--     Ahi se aplica la regla de 'totalidad de una edicion' del
--     enunciado: todos sus partidos, sus 32 selecciones, y los
--     26 convocados de cada una.
--
-- Reglas de formato del archivo:
--   * Un INSERT explicito por fila en la parte base, igual que en
--     la Entrega 1, para poder leer la secuencia del campeonato.
--   * INSERT ... SELECT para las estadisticas y las asignaciones
--     arbitrales, que son filas derivadas de tablas ya cargadas.
--   * Los nombres de jugadores, arbitros y cuerpo tecnico son
--     inventados (como los estadios de la Entrega 1), pero los
--     dorsales, posiciones, cargos y nacionalidades siguen las
--     reglas reales del reglamento.
--
-- Conjuntos resultantes:
--   EDICION_MUNDIAL 7 | SEDE 8 | CIUDAD 112 | ESTADIO 112
--   FASE 42 | GRUPO 56 | SELECCION 224 | PARTIDO 448
--   PARTICIPACION 896 | JUGADOR 832 | CONVOCATORIA 832
--   CUERPO_TECNICO 160 | ARBITRO 120 | ASIGNACION 384
--   ESTADISTICA 2048 | INCIDENCIA 32
-- ============================================================

-- ------------------------------------------------------------
-- 1. EDICION_MUNDIAL  (7 filas)
-- ------------------------------------------------------------
-- Las mismas siete ediciones de la Entrega 1. La sede deja de ser
-- columna y pasa a la tabla SEDE, que admite dos paises para el 2002.
VALUES (1, 1998, 'El futbol nos une', DATE '1998-06-10', DATE '1998-07-12');
VALUES (2, 2002, 'Dos naciones, un torneo', DATE '2002-05-31', DATE '2002-06-30');
VALUES (3, 2006, 'El mundo entre amigos', DATE '2006-06-09', DATE '2006-07-09');
VALUES (4, 2010, NULL, DATE '2010-06-11', DATE '2010-07-11');
VALUES (5, 2014, 'Todos en un mismo ritmo', DATE '2014-06-12', DATE '2014-07-13');
VALUES (6, 2018, 'De este a oeste', DATE '2018-06-14', DATE '2018-07-15');
VALUES (7, 2022, 'Ahora es el momento', DATE '2022-11-20', DATE '2022-12-18');

-- ------------------------------------------------------------
-- 2. SEDE  (8 filas)
-- ------------------------------------------------------------
-- Corea y Japon organizaron el Mundial 2002 juntos, por eso esa
-- edicion tiene dos sedes y las demas una.

-- ------------------------------------------------------------
-- 3. CIUDAD  (112 filas)
-- ------------------------------------------------------------
-- Una ciudad por estadio, colgada de la sede de su edicion. En el
-- 2002 las ocho ciudades coreanas van a la sede de Corea y las ocho
-- japonesas a la de Japon.

-- ------------------------------------------------------------
-- 4. ESTADIO  (112 filas)
-- ------------------------------------------------------------
-- El estadio ahora depende de la ciudad; la capacidad se conserva.

-- ------------------------------------------------------------
-- 5. FASE  (42 filas -- 6 por edicion)
-- ------------------------------------------------------------
-- Fase de grupos y las cuatro de eliminacion directa. La fase de
-- grupos es tipo GRUPOS y el resto ELIMINATORIA. La fase Dieciseisavos
-- no se usa en ninguna edicion de los datos.

-- ------------------------------------------------------------
-- 6. GRUPO  (56 filas -- 8 grupos A..H por edicion)
-- ------------------------------------------------------------
-- Cada grupo cuelga de la fase de grupos de su edicion. En todos
-- los datos el formato es de 8 grupos de 4 selecciones.

-- ------------------------------------------------------------
-- 7. SELECCION  (224 filas -- 32 por edicion)
-- ------------------------------------------------------------
-- El grupo ya no es una letra suelta: es llave foranea a GRUPO.
-- Todas las selecciones de los datos caen en alguno de los ocho
-- grupos de su edicion, por eso id_grupo nunca es nulo aqui.

-- ------------------------------------------------------------
-- 8. PARTIDO  (448 filas -- 64 por edicion)
-- ------------------------------------------------------------
-- Los 48 de grupos y los 16 de eliminacion de cada edicion.
-- id_partido_siguiente arma el cuadro: los octavos apuntan al cuarto
-- que le toca al ganador, los cuartos a la semifinal y las dos
-- semifinales a la final. Los partidos de grupos, el Tercer Puesto y
-- la Final no tienen siguiente, asi que quedan nulos.

-- ------------------------------------------------------------
-- 9. PARTICIPACION_PARTIDO  (896 filas)
-- ------------------------------------------------------------
-- Idem a la Entrega 1: dos filas por partido (LOCAL/VISITANTE) con
-- sus goles. Ningun empate en las fases de eliminacion.

-- ------------------------------------------------------------
-- 10-11. JUGADOR y CONVOCATORIA_JUGADOR  (832 + 832 filas)
-- ------------------------------------------------------------
-- Cada una de las 32 selecciones de la edicion 7 convoca 26
-- jugadores (el cupo maximo desde el Mundial 2022). Los nombres son
-- inventados pero plausibles por region, y los dorsales siguen la
-- numeracion clasica del futbol (el 10 es el capitan).
-- 
-- Un jugador se registra una sola vez en JUGADOR (id_jugador
-- global 1..832) y la convocatoria lo enlaza con su seleccion y su
-- dorsal en esa edicion.
-- JUGADOR ----------------------------------------------------

-- CONVOCATORIA_JUGADOR ---------------------------------------

-- ------------------------------------------------------------
-- 12. CUERPO_TECNICO  (160 filas -- 5 por seleccion)
-- ------------------------------------------------------------
-- Los cargos que admite el CHECK del DDL: director tecnico, asistente
-- tecnico, preparador fisico, entrenador de porteros y medico.

-- ------------------------------------------------------------
-- 13. ARBITRO  (120 filas)
-- ------------------------------------------------------------
-- Ternas de todas las confederaciones, como en un Mundial real.
-- Nombres inventados.
-- ARBITRO ----------------------------------------------------

-- ------------------------------------------------------------
-- 14. ASIGNACION_ARBITRAL  (384 filas -- 6 roles x 64 partidos)
-- ------------------------------------------------------------
-- Cada partido de la edicion 7 tiene Principal, Asistente 1, Asistente
-- 2, Cuarto arbitro, VAR y AVAR. Los roles se asignan desde la tabla
-- ARBITRO con una rotacion por MODULO que nunca repite el mismo
-- arbitro en un partido (los saltos entre roles no son multiples de
-- 120, la cantidad de arbitros). El mismo arbitro puede pitar mas de
-- un partido por dia razonable en un Mundial.

-- 64 partidos x 6 roles. La asignacion sale de: para el partido p y el
-- rol r (0..5), el arbitro es MOD((p - 385) * 6 + salto[r], 120) + 1.
SELECT (pt.id_partido - 385) * 6 + rr.rn,
       pt.id_partido,
       MOD((pt.id_partido - 385) * 6 + rr.salto, 120) + 1,
       rr.rol
FROM (SELECT id_partido FROM partido WHERE id_edicion = 7) pt
CROSS JOIN (
       SELECT 1 AS rn, 0   AS salto, 'Principal'      AS rol FROM dual UNION ALL
       SELECT 2,       19,         'Asistente 1'           FROM dual UNION ALL
       SELECT 3,       41,         'Asistente 2'           FROM dual UNION ALL
       SELECT 4,       53,         'Cuarto arbitro'        FROM dual UNION ALL
       SELECT 5,       83,         'VAR'                   FROM dual UNION ALL
       SELECT 6,       107,        'AVAR'                  FROM dual
       ) rr
ORDER BY pt.id_partido, rr.rn;


-- ------------------------------------------------------------
-- 15. ESTADISTICA_JUGADOR_PARTIDO  (2048 filas)
-- ------------------------------------------------------------
-- El rendimiento de los 16 que jugaron por seleccion en cada partido
-- de la edicion 7 (los 11 titulares mas 5 cambios, como permite el
-- reglamento actual). La estadistica deriva de tablas ya cargadas:
-- 
--   - los 11 primeros dorsales inician; los dorsales 12-16 entran
--     entre el minuto 46 y el 66
--   - los goles del partido se reparten de menor a mayor dorsal entre
--     los delanteros, de modo que la SUMA de goles de la estadistica
--     coincide con goles_marcados de PARTICIPACION_PARTIDO (regla de
--     coherencia del modelo). El maximo de goles en los datos es 4
--     y hay 16 jugadores por equipo, asi que siempre alcanza.
--   - amarillas y asistencias siguen un patron simple (una amarilla
--     cada 7 dorsales, una asistencia cada 3).

-- 64 partidos x 2 selecciones x 16 jugadores = 2048 filas.
-- id_estadistica se numeran en orden de partido, seleccion y dorsal.
   minuto_salida, minutos_jugados, goles, asistencias, tarjetas_amarillas,
   tarjetas_rojas)
SELECT ROW_NUMBER() OVER (ORDER BY pp.id_partido, pp.id_seleccion, cj.numero_camiseta),
       pp.id_partido,
       cj.id_jugador,
       CASE WHEN cj.numero_camiseta <= 11 THEN 1 ELSE 0 END,
       CASE WHEN cj.numero_camiseta <= 11 THEN NULL
            ELSE 46 + (cj.numero_camiseta - 12) * 5 END,
       CASE WHEN cj.numero_camiseta = 9  AND pp.goles_marcados >= 1 THEN 78
            WHEN cj.numero_camiseta = 10 THEN 74
            ELSE NULL END,
       CASE WHEN cj.numero_camiseta <= 11 THEN
            CASE WHEN cj.numero_camiseta = 9  AND pp.goles_marcados >= 1 THEN 78
                 WHEN cj.numero_camiseta = 10 THEN 74
                 ELSE 90 END
            ELSE 90 - (46 + (cj.numero_camiseta - 12) * 5) END,
       -- Goles: se reparten entre los delanteros (dorsales 9 a 16 con
       -- prioridad 9,10,11,12,13,14,16) de menor prioridad a mayor hasta
       -- completar goles_marcados. Asi la suma por equipo coindice con la
       -- participacion y nunca excede max 7 goleadores.
       CASE WHEN cj.numero_camiseta = 9  AND pp.goles_marcados >= 1 THEN 1
            WHEN cj.numero_camiseta = 10 AND pp.goles_marcados >= 2 THEN 1
            WHEN cj.numero_camiseta = 11 AND pp.goles_marcados >= 3 THEN 1
            WHEN cj.numero_camiseta = 12 AND pp.goles_marcados >= 4 THEN 1
            WHEN cj.numero_camiseta = 13 AND pp.goles_marcados >= 5 THEN 1
            WHEN cj.numero_camiseta = 14 AND pp.goles_marcados >= 6 THEN 1
            WHEN cj.numero_camiseta = 16 AND pp.goles_marcados >= 7 THEN 1
            ELSE 0 END,
       CASE WHEN MOD(cj.numero_camiseta, 3) = 0 THEN 1 ELSE 0 END,
       CASE WHEN MOD(cj.numero_camiseta, 7) = 0 THEN 1 ELSE 0 END,
       0
FROM participacion_partido pp
JOIN convocatoria_jugador cj ON cj.id_seleccion = pp.id_seleccion
WHERE pp.id_partido BETWEEN 385 AND 448
  AND cj.numero_camiseta <= 16
ORDER BY pp.id_partido, pp.id_seleccion, cj.numero_camiseta;


